340   static constexpr FPClassTest OrderedLessThanZeroMask =
341       fcNegSubnormal | fcNegNormal | fcNegInf;
342   static constexpr FPClassTest OrderedGreaterThanZeroMask =
343       fcPosSubnormal | fcPosNormal | fcPosInf;
